"""Phase 1 MOCK screening sub-scores (step 2a). Generated by code, NOT by an AI model (team decision, SPEC §18).

Simple CPV / NUTS / value overlap plus a few keyword hints, so that every screening mode appears. The output has the
exact ScreeningOutput schema of Phase 2; the aggregation, confidence and routing that follow are the real code (§6).
"""
from __future__ import annotations

from .. import schemas

MOCK_MODEL = "none (mock generated by code)"
M = 1_000_000

# Keyword hints derived from each profile's CPV labels and lot preferences (mock only).
KEYWORDS = {
    "P1": ["ombygging", "rehabilitering", "renovering", "tømrer", "bygg"],
    "P2": ["vann", "avløp", "vei", "va-"],
    "P3": ["slam", "slamavskill", "septik", "spyling", "avløp"],
}


def field(profile: dict, fid: str) -> dict | None:
    for sec in ("search_profile", "capability_locker"):
        for e in profile[sec]:
            if e["id"] == fid:
                return e
    return None


def S(value, en, nb, dps):
    return {"value": None if value is None else int(round(max(0, min(100, value)))), "reason_en": en, "reason_nb": nb,
            "data_points": dps}


def cpv_score(codes: list[str], main: list[str], secondary: list[str]) -> tuple[int, str, str]:
    best, why = 5, None
    prof = [(c, "main") for c in main] + [(c, "secondary") for c in secondary]
    for idx, nc in enumerate(codes):
        factor = 1.0 if idx == 0 else 0.95
        for pc, kind in prof:
            if nc == pc:
                s = 95 if kind == "main" else 88
            else:
                L = 0
                while L < 8 and nc[L] == pc[L]:
                    L += 1
                s = {8: 95, 7: 80, 6: 78, 5: 75, 4: 65, 3: 55, 2: 40}.get(L, 5)
            s *= factor
            if s > best:
                best, why = s, (nc, pc, kind)
    if why is None:
        return 5, "No CPV overlap with the profile", "Ingen CPV-overlapp med profilen"
    nc, pc, kind = why
    if nc == pc:
        return round(best), f"CPV {nc} equals the firm's {kind} CPV", f"CPV {nc} er lik firmaets {'hoved' if kind == 'main' else 'sekundære'}-CPV"
    return round(best), f"CPV {nc} is related to the firm's {kind} CPV {pc} (shared prefix)", \
        f"CPV {nc} er beslektet med firmaets CPV {pc} (felles prefiks)"


def kw_hits(text: str, pid: str) -> list[str]:
    t = text.lower()
    return [k for k in KEYWORDS[pid] if k in t]


def infer_contract_form(o: dict) -> str:
    d = (o.get("description", "") + " " + o.get("title", "")).lower()
    if o.get("contract_type") != "Works":
        return "direct"
    if "prosjektering og gjennomføring" in d or "totalentreprise" in d:
        return "design_and_build"
    return "execution"


def screen(rec: dict, profile: dict, lots: list[dict], prompt_version: str) -> tuple[dict, dict]:
    pid = profile["profile_id"]
    o, d = rec["original"], rec["derived"]
    main = field(profile, "main_cpv")["structured"]["codes"]
    sec = field(profile, "secondary_cpv")["structured"]["codes"]
    nuts = field(profile, "region_nuts")["structured"]["codes"]
    subj = field(profile, "contract_subject")["structured"]["subjects"]
    form = field(profile, "contract_form")["structured"]
    band = field(profile, "size_band")["structured"]
    fd = field(profile, "framework_dps")["structured"]
    lp = field(profile, "lot_preferences")["structured"]
    subs, contradictions, notes_en, notes_nb = {}, [], [], []

    # subject relevance -----------------------------------------------------------------------------------------
    cs, en, nb = cpv_score(d["cpv_all"], main, sec)
    hits = kw_hits(o["title"] + " " + o.get("title_en", "") + " " + o["description"], pid)
    if hits and cs >= 40:
        cs = min(100, cs + 4)
        en += f"; title/description mention {', '.join(hits)}"
        nb += f"; tittel/beskrivelse nevner {', '.join(hits)}"
    subs["subject_relevance"] = S(cs, en, nb, ["title", "title_en", "description", "cpv_main", "cpv_additional", "trade"])

    # region ----------------------------------------------------------------------------------------------------
    place = d["place_of_performance_nuts_list"]
    buyer = d["buyer_nuts_list"]
    if not place:
        subs["region"] = S(None, "Place of performance missing", "Utførelsessted mangler", ["place_of_performance_nuts"])
    elif d["place_anywhere"]:
        subs["region"] = S(100, "Place of performance 'anyw' = anywhere in Norway: compatible with every region",
                           "Utførelsessted «anyw» = hele Norge: forenlig med alle regioner", ["place_of_performance_nuts"])
    elif any(p in nuts for p in place):
        hit = [p for p in place if p in nuts]
        subs["region"] = S(100, f"Place of performance {', '.join(hit)} is in the firm's region",
                           f"Utførelsessted {', '.join(hit)} ligger i firmaets region", ["place_of_performance_nuts"])
    else:
        near = any(p[:4] == n[:4] for p in place for n in nuts)
        if any(b in nuts for b in buyer):
            subs["region"] = S(60, f"Place of performance {', '.join(place)} lies outside the firm's region, but the buyer "
                                   f"is located in it ({', '.join(buyer)})",
                               f"Utførelsessted {', '.join(place)} ligger utenfor firmaets region, men oppdragsgiver "
                               f"holder til der ({', '.join(buyer)})", ["place_of_performance_nuts", "buyer_nuts"])
            contradictions.append({"code": "nuts_vs_buyer_location",
                                   "description_en": f"Place of performance coded {', '.join(place)} although the buyer is "
                                                     f"in {', '.join(buyer)}",
                                   "description_nb": f"Utførelsessted kodet {', '.join(place)} selv om oppdragsgiver er i "
                                                     f"{', '.join(buyer)}"})
        else:
            subs["region"] = S(45 if near else 0,
                               f"Place of performance {', '.join(place)} is outside the firm's region"
                               + (" (same NUTS-2 area)" if near else ""),
                               f"Utførelsessted {', '.join(place)} ligger utenfor firmaets region"
                               + (" (samme NUTS-2-område)" if near else ""), ["place_of_performance_nuts"])
    if not buyer:
        notes_en.append("buyer_nuts is empty; region scored from place of performance only")
        notes_nb.append("buyer_nuts er tomt; regionen er vurdert ut fra utførelsessted alene")

    # contract subject ------------------------------------------------------------------------------------------
    ct = o.get("contract_type", "")
    if not ct:
        subs["contract_subject"] = S(None, "Contract type missing", "Kontraktstype mangler", ["contract_type"])
    else:
        ok = ct in subj
        subs["contract_subject"] = S(100 if ok else 0, f"Contract type {ct} {'matches' if ok else 'differs from'} "
                                                       f"the firm's {', '.join(subj)}",
                                     f"Kontraktstype {ct} {'samsvarer med' if ok else 'avviker fra'} firmaets "
                                     f"{', '.join(subj)}", ["contract_type"])

    # contract form (inferred from the description) ---------------------------------------------------------------
    cf = infer_contract_form(o)
    if cf == "direct":
        subs["contract_form"] = S(None, "Contract form not applicable to a supplies/services contract",
                                  "Kontraktsform er ikke relevant for vare-/tjenestekontrakter", ["description"])
    elif cf == "design_and_build":
        if form.get("design_and_build"):
            val = d["estimated_value_nok"]
            within = val is None or val <= form.get("design_and_build_max_nok", float("inf"))
            subs["contract_form"] = S(85 if within else 40,
                                      "Description includes design and execution (design-and-build); the firm accepts "
                                      f"design-and-build {form.get('design_and_build_note', '')}".strip(),
                                      "Beskrivelsen omfatter prosjektering og gjennomføring (totalentreprise); firmaet "
                                      "tar totalentrepriser med ekstern prosjekterende", ["description"])
        else:
            subs["contract_form"] = S(30 if form.get("subcontractor") else 0,
                                      "Design-and-build contract; the firm only takes part as subcontractor",
                                      "Totalentreprise; firmaet deltar bare som underleverandør", ["description"])
    else:
        if form.get("execution"):
            subs["contract_form"] = S(100, "Execution contract; the firm accepts execution contracts",
                                      "Utførelsesentreprise; firmaet tar utførelsesentrepriser", ["description"])
        else:
            subs["contract_form"] = S(30 if form.get("subcontractor") else 0,
                                      "Execution contract; the firm only takes part as subcontractor",
                                      "Utførelsesentreprise; firmaet deltar bare som underleverandør", ["description"])

    # size ------------------------------------------------------------------------------------------------------
    val = d["estimated_value_nok"]
    if val is None:
        why = "zero (0) is treated as unknown" if d["estimated_value_status"] == "zero_treated_as_unknown" else "missing"
        subs["size"] = S(None, f"Estimated value {why}: excluded from the score",
                         f"Estimert verdi {'0 behandles som ukjent' if 'zero' in why else 'mangler'}: holdt utenfor scoren",
                         ["estimated_value"])
    else:
        interp = val
        basis_en, basis_nb = "", ""
        lots_n = d["lot_count_int"] or 1
        parallel = "parallelle rammeavtaler" in o["description"].lower()
        if d["framework"] and (lots_n > 1 or parallel):
            interp = val / lots_n / (2 if parallel else 1)
            basis_en = f"; aggregate NOK {val / M:g}m; interpreted ≈ NOK {interp / M:.1f}m per lot and supplier"
            basis_nb = f"; samlet NOK {val / M:g} mill.; tolket ≈ NOK {interp / M:.1f} mill. per delkontrakt og leverandør"
        lo, hi = band["min_nok"], band["max_nok"]
        if lo <= interp <= hi:
            sc = 100 if interp == val else 80
            en = f"Value within the firm's band NOK {lo / M:g}–{hi / M:g}m{basis_en}"
            nb = f"Verdien ligger innenfor firmaets intervall NOK {lo / M:g}–{hi / M:g} mill.{basis_nb}"
        elif interp > hi:
            sc = max(10, 100 * hi / interp)
            en = f"Value above the firm's band (max NOK {hi / M:g}m){basis_en}"
            nb = f"Verdien er over firmaets intervall (maks NOK {hi / M:g} mill.){basis_nb}"
        else:
            sc = max(10, 100 * interp / lo)
            en = f"Value below the firm's band (min NOK {lo / M:g}m)"
            nb = f"Verdien er under firmaets intervall (min NOK {lo / M:g} mill.)"
        subs["size"] = S(sc, en, nb, ["estimated_value", "framework_agreement", "lot_count", "description"])
        if interp != val and val > hi:
            contradictions.append({"code": "aggregate_vs_calloff_value",
                                   "description_en": f"Aggregate framework value NOK {val / M:g}m exceeds the band, while the "
                                                     f"expected call-off volume per supplier may fit; interpreted, not compared blindly",
                                   "description_nb": f"Samlet rammeverdi NOK {val / M:g} mill. er over intervallet, mens "
                                                     f"forventet avropsvolum per leverandør kan passe; tolket, ikke "
                                                     f"sammenlignet direkte"})

    # framework / DPS -------------------------------------------------------------------------------------------
    if d["dps"]:
        v = fd.get("dps")
        subs["framework_dps"] = S(None if v is None else (100 if v else 0),
                                  "Dynamic purchasing system; firm's DPS preference " +
                                  ("declared missing: excluded" if v is None else ("yes" if v else "no")),
                                  "Dynamisk innkjøpsordning; firmaets DPS-preferanse " +
                                  ("erklært manglende: holdt utenfor" if v is None else ("ja" if v else "nei")),
                                  ["dynamic_purchasing_system"])
    elif d["framework"]:
        v = fd.get("framework")
        subs["framework_dps"] = S(100 if v else 0, f"Framework agreement; firm willing: {'yes' if v else 'no'}"
                                  + ("; parallel frameworks accepted" if fd.get("parallel_framework") else ""),
                                  f"Rammeavtale; firmaet villig: {'ja' if v else 'nei'}"
                                  + ("; parallelle rammeavtaler akseptert" if fd.get("parallel_framework") else ""),
                                  ["framework_agreement"])
    else:
        subs["framework_dps"] = S(100, "Ordinary contract (no framework, no DPS)",
                                  "Ordinær kontrakt (ikke rammeavtale eller DPS)",
                                  ["framework_agreement", "dynamic_purchasing_system"])

    # lots ------------------------------------------------------------------------------------------------------
    lot_scores = []
    if not lots:
        subs["lots"] = S(100, "Single contract (no lots)", "Én kontrakt (ingen delkontrakter)", ["lot_count"])
    else:
        subs["lots"] = S(70, f"{len(lots)} lots; assessed per lot", f"{len(lots)} delkontrakter; vurdert per delkontrakt",
                         ["lot_count", "description"])
        per_lot_val = (val / len(lots)) if val else None
        for lot in lots:
            h = kw_hits(lot["title_nb"], pid)
            disc = lp.get("disciplines")
            if disc is not None:
                if h:
                    s_sub = S(92, f"Lot {lot['lot_id']} ({lot['title_en']}) is in the firm's disciplines ({', '.join(h)})",
                              f"Delkontrakt {lot['lot_id']} ({lot['title_nb']}) er innenfor firmaets fagområder ({', '.join(h)})",
                              ["description", "cpv_additional"])
                    s_lot = S(100, "Lot matches the firm's lot preferences (only water, sewer or road)",
                              "Delkontrakten passer firmaets preferanser (bare vann, avløp eller vei)", ["description"])
                else:
                    s_sub = S(min(30, cs), f"Lot {lot['lot_id']} ({lot['title_en']}) is outside the firm's disciplines",
                              f"Delkontrakt {lot['lot_id']} ({lot['title_nb']}) er utenfor firmaets fagområder",
                              ["description", "cpv_additional"])
                    s_lot = S(0, "Lot outside the firm's lot preferences (only water, sewer or road)",
                              "Delkontrakten er utenfor firmaets preferanser (bare vann, avløp eller vei)", ["description"])
            else:
                s_sub = dict(subs["subject_relevance"])
                pref = lp.get("preferred_max_lot_value_nok")
                if pref and per_lot_val and per_lot_val > pref:
                    s_lot = S(40, f"Lot value ≈ NOK {per_lot_val / M:.0f}m above the preferred NOK {pref / M:g}m",
                              f"Delkontraktsverdi ≈ NOK {per_lot_val / M:.0f} mill. over foretrukket NOK {pref / M:g} mill.",
                              ["estimated_value", "lot_count"])
                else:
                    s_lot = S(70, "No specific lot preference applies", "Ingen særskilt preferanse for delkontrakter",
                              ["lot_count"])
            lot_scores.append({"lot_id": lot["lot_id"], "subject_relevance": s_sub, "lots": s_lot,
                               "relevant": False})
    if not o.get("title_en"):
        notes_en.append("title_en is empty; Norwegian title used")
        notes_nb.append("title_en er tomt; norsk tittel brukt")
    out = {"firm_id": pid, "notice_id": rec["doffin_id"], "notice_version_hash": rec["version_hash"],
           "prompt_version": prompt_version, "model": MOCK_MODEL, "sub_scores": subs, "lot_scores": lot_scores,
           "contradictions": contradictions, "data_quality_notes_en": notes_en, "data_quality_notes_nb": notes_nb,
           "mock": True}
    ok, validated, errs = schemas.validate(schemas.ScreeningOutput, out)
    return {"raw": out, "schema_ok": ok, "schema_errors": errs, "validated": validated}, prompt_input(rec, profile)


def prompt_input(rec: dict, profile: dict) -> dict:
    """Exactly what the screening prompt receives: all notice fields except contact fields + the search profile."""
    contact = {"contact_name", "contact_email", "contact_phone"}
    return {"notice": {k: v for k, v in rec["original"].items() if k not in contact},
            "search_profile": [{"id": e["id"], "label": e["label_en"], "value": e["value"],
                                "proof_status": e["proof_status_original"]} for e in profile["search_profile"]]}
